const FONT_LINK_ID = "telugu-font-link";

function useTeluguFont() {
  useEffect(() => {
    if (document.getElementById(FONT_LINK_ID)) return;
    const link = document.createElement("link");
    link.id = FONT_LINK_ID;
    link.rel = "stylesheet";
    link.href =
      "https://fonts.googleapis.com/css2?family=Noto+Sans+Telugu:wght@400;500;600;700&family=Noto+Serif+Telugu:wght@500;600;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

function normalize(s) {
  return (s || "").toLowerCase();
}

// Strips everything but a-z0-9 and collapses runs of the same letter down to
// one (so "yehoovaa" and "yehova" both become "yehova"). This lets
// English-script search match the precomputed roman transliteration without
// the user needing to guess exact long-vowel spelling, double consonants,
// spacing or punctuation.
function normalizeRoman(s) {
  return (s || "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "")
    .replace(/(.)\1+/g, "$1");
}

// Deterministic Telugu -> plain-ASCII roman transliteration, used to show
// lyrics in English script. Not a scholarly scheme -- just phonetic enough
// to sing along from.
const TG_VOWEL_INDEPENDENT = {
  "అ": "a", "ఆ": "aa", "ఇ": "i", "ఈ": "ii", "ఉ": "u", "ఊ": "uu",
  "ఋ": "ru", "ౠ": "ruu", "ఌ": "lu", "ౡ": "luu",
  "ఎ": "e", "ఏ": "ee", "ఐ": "ai", "ఒ": "o", "ఓ": "oo", "ఔ": "au",
};
const TG_VOWEL_SIGN = {
  "ా": "aa", "ి": "i", "ీ": "ii", "ు": "u", "ూ": "uu",
  "ృ": "ru", "ౄ": "ruu", "ె": "e", "ే": "ee", "ై": "ai",
  "ొ": "o", "ో": "oo", "ౌ": "au",
};
const TG_CONSONANT = {
  "క": "k", "ఖ": "kh", "గ": "g", "ఘ": "gh", "ఙ": "ng",
  "చ": "ch", "ఛ": "chh", "జ": "j", "ఝ": "jh", "ఞ": "ny",
  "ట": "t", "ఠ": "th", "డ": "d", "ఢ": "dh", "ణ": "n",
  "త": "t", "థ": "th", "ద": "d", "ధ": "dh", "న": "n",
  "ప": "p", "ఫ": "ph", "బ": "b", "భ": "bh", "మ": "m",
  "య": "y", "ర": "r", "ల": "l", "వ": "v",
  "శ": "sh", "ష": "sh", "స": "s", "హ": "h",
  "ళ": "l", "ఱ": "r", "ఴ": "l",
};
const TG_VIRAMA = "్";
const TG_ANUSVARA = "ం";
const TG_VISARGA = "ః";
const TG_CHANDRABINDU = "ఁ";
const TG_DIGIT = {
  "౦": "0", "౧": "1", "౨": "2", "౩": "3", "౪": "4",
  "౫": "5", "౬": "6", "౭": "7", "౮": "8", "౯": "9",
};

function teluguToRoman(str) {
  const s = str || "";
  const chars = Array.from(s);
  let out = "";
  for (let i = 0; i < chars.length; i++) {
    const c = chars[i];
    if (TG_VOWEL_INDEPENDENT[c] !== undefined) {
      out += TG_VOWEL_INDEPENDENT[c];
      continue;
    }
    if (TG_DIGIT[c] !== undefined) {
      out += TG_DIGIT[c];
      continue;
    }
    if (c === TG_ANUSVARA || c === TG_CHANDRABINDU) {
      out += "m";
      continue;
    }
    if (c === TG_VISARGA) {
      out += "h";
      continue;
    }
    if (c === TG_VIRAMA) {
      continue;
    }
    if (TG_CONSONANT[c] !== undefined) {
      const next = chars[i + 1];
      if (next === TG_VIRAMA) {
        out += TG_CONSONANT[c];
        i++;
        continue;
      }
      if (next !== undefined && TG_VOWEL_SIGN[next] !== undefined) {
        out += TG_CONSONANT[c] + TG_VOWEL_SIGN[next];
        i++;
        continue;
      }
      out += TG_CONSONANT[c] + "a";
      continue;
    }
    if (c === "।" || c === "॥") {
      out += " ";
      continue;
    }
    out += c;
  }
  return out.replace(/\s+/g, " ").trim();
}

// Capitalizes the first letter of each word, for nicer display than the
// all-lowercase form used internally for search matching.
function titleCaseRoman(s) {
  return (s || "").replace(/[a-z]+/gi, (w) => w.charAt(0).toUpperCase() + w.slice(1));
}

function romanizeSong(song) {
  if (!song) return song;
  return {
    ...song,
    title: titleCaseRoman(song.titleRoman || teluguToRoman(song.title)),
    composer: song.composer ? titleCaseRoman(song.composerRoman || teluguToRoman(song.composer)) : song.composer,
    ref: song.ref ? teluguToRoman(song.ref) : song.ref,
    refrain: song.refrain
      ? {
          label: song.refrain.label ? titleCaseRoman(teluguToRoman(song.refrain.label)) : song.refrain.label,
          lines: song.refrain.lines.map((l) => teluguToRoman(l)),
        }
      : song.refrain,
    verses: (song.verses || []).map((v) => ({
      ...v,
      lines: v.lines.map((l) => teluguToRoman(l)),
    })),
  };
}

const SCRIPT_MODE_KEY = "zion-songs-script-mode";

function loadScriptMode() {
  try {
    const v = window.localStorage.getItem(SCRIPT_MODE_KEY);
    if (v === "en" || v === "te") return v;
  } catch (e) {}
  return "te";
}

const LIGHT_COLORS = {
  bg: "#faf6ee",
  ink: "#2c2410",
  accent: "#7a1f2b",
  gold: "#a9793f",
  goldSoft: "#c98a2c",
  border: "#ecdfc4",
  borderStrong: "#e3d6bb",
  cardBg: "#fff",
  refrainBg: "#fbf3e2",
  chipBg: "#f6ead6",
  chipText: "#8a4b16",
  mutedText: "#8a7a5a",
  pendingBg: "#f2ede0",
  pendingText: "#b0a486",
  markBg: "#f0dcae",
  markText: "#4a1b0c",
  disabled: "#c9bfa5",
};

const DARK_COLORS = {
  bg: "#171009",
  ink: "#f2e9d8",
  accent: "#e3a35e",
  gold: "#caa06a",
  goldSoft: "#dcb679",
  border: "#3c3122",
  borderStrong: "#4c3d29",
  cardBg: "#221a12",
  refrainBg: "#2a2015",
  chipBg: "#3a2a17",
  chipText: "#e6b876",
  mutedText: "#b6a68a",
  pendingBg: "#241f18",
  pendingText: "#7d7260",
  markBg: "#5c4621",
  markText: "#f6e2b2",
  disabled: "#5c5243",
};

// Mutated in place when the theme toggles, so every component reading
// COLORS.xxx during render sees the current theme without prop drilling.
const COLORS = { ...LIGHT_COLORS };

function applyPalette(isDark) {
  Object.assign(COLORS, isDark ? DARK_COLORS : LIGHT_COLORS);
}

const DARK_MODE_KEY = "zion-songs-dark-mode";

function loadDarkMode() {
  try {
    return window.localStorage.getItem(DARK_MODE_KEY) === "1";
  } catch (e) {}
  return false;
}

const FONT_SCALE_MIN = 0.8;
const FONT_SCALE_MAX = 2;
const FONT_SCALE_STEP = 0.1;
const FONT_SCALE_KEY = "zion-songs-font-scale";

function loadFontScale() {
  try {
    const saved = window.localStorage.getItem(FONT_SCALE_KEY);
    const n = parseFloat(saved);
    if (!isNaN(n) && n >= FONT_SCALE_MIN && n <= FONT_SCALE_MAX) return n;
  } catch (e) {}
  return 1;
}

export default function SongbookApp() {
  useTeluguFont();

  const [showSplash, setShowSplash] = useState(true);
  const [query, setQuery] = useState("");
  const [activeNum, setActiveNum] = useState(null);
  const [activeSection, setActiveSection] = useState(null);
  const [alphaMode, setAlphaMode] = useState(false);
  const [fontScale, setFontScale] = useState(loadFontScale);
  const [scriptMode, setScriptMode] = useState(loadScriptMode);
  const [darkMode, setDarkMode] = useState(loadDarkMode);
  const inputRef = useRef(null);

  // Keep the shared COLORS object in sync with the current theme before
  // this render (and any child components rendered within it) read it.
  applyPalette(darkMode);

  function toggleDarkMode() {
    setDarkMode((prev) => {
      const next = !prev;
      try {
        window.localStorage.setItem(DARK_MODE_KEY, next ? "1" : "0");
      } catch (e) {}
      return next;
    });
  }

  function toggleScriptMode() {
    setScriptMode((prev) => {
      const next = prev === "en" ? "te" : "en";
      try {
        window.localStorage.setItem(SCRIPT_MODE_KEY, next);
      } catch (e) {}
      return next;
    });
  }

  function changeFontScale(delta) {
    setFontScale((prev) => {
      const next = Math.min(FONT_SCALE_MAX, Math.max(FONT_SCALE_MIN, Math.round((prev + delta) * 100) / 100));
      try {
        window.localStorage.setItem(FONT_SCALE_KEY, String(next));
      } catch (e) {}
      return next;
    });
  }

  const sorted = useMemo(() => [...SONGS].sort((a, b) => a.num - b.num), []);

  const alphaSorted = useMemo(
    () => [...SONGS].sort((a, b) => (a.title || "").localeCompare(b.title || "", "te")),
    []
  );

  const results = useMemo(() => {
    const q = query.trim();
    if (!q) return [];
    const qNorm = normalize(q);
    const qRoman = normalizeRoman(q);
    const isNumeric = /^\d+$/.test(q);
    return sorted.filter((s) => {
      if (isNumeric) {
        return String(s.num) === q || String(s.num).startsWith(q);
      }
      if (normalize(s.title).includes(qNorm) || normalize(s.composer).includes(qNorm)) {
        return true;
      }
      // English-script (romanized) search, e.g. typing "yehova" finds "యెహోవా".
      if (qRoman.length >= 2) {
        if (normalizeRoman(s.titleRoman).includes(qRoman)) return true;
        if (normalizeRoman(s.composerRoman).includes(qRoman)) return true;
      }
      return false;
    });
  }, [query, sorted]);

  const sectionSongs = useMemo(() => {
    if (!activeSection) return [];
    const [lo, hi] = activeSection.range;
    return sorted.filter((s) => s.num >= lo && s.num <= hi);
  }, [sorted, activeSection]);

  // the list we navigate prev/next within: a section when one is open, else the full list
  const navList = activeSection ? sectionSongs : sorted;

  const activeIndex = useMemo(() => navList.findIndex((s) => s.num === activeNum), [navList, activeNum]);
  const activeSong = activeIndex >= 0 ? navList[activeIndex] : null;

  function openSong(num) {
    setActiveNum(num);
  }
  function openSection(sec) {
    setActiveSection(sec);
    setAlphaMode(false);
    setActiveNum(null);
    setQuery("");
  }
  function backToContents() {
    setActiveSection(null);
  }
  function openAlphaList() {
    setAlphaMode(true);
    setActiveSection(null);
    setActiveNum(null);
    setQuery("");
  }
  function goPrev() {
    if (activeIndex > 0) setActiveNum(navList[activeIndex - 1].num);
  }
  function goNext() {
    if (activeIndex >= 0 && activeIndex < navList.length - 1) setActiveNum(navList[activeIndex + 1].num);
  }
  function backToSearch() {
    setActiveNum(null);
  }

  const teluguBody = { fontFamily: "'Noto Sans Telugu', sans-serif" };
  const teluguDisplay = { fontFamily: "'Noto Serif Telugu', serif" };

  if (showSplash) {
    const cornerOrnament = (pos, cssTransform) => (
      <svg
        width="72"
        height="72"
        viewBox="0 0 100 100"
        fill="none"
        style={{ position: "absolute", ...pos, transform: cssTransform, opacity: 0.8 }}
      >
        <path d="M6 46 Q46 46 46 6" stroke={COLORS.goldSoft} strokeWidth="2" />
        <path d="M6 70 Q70 70 70 6" stroke={COLORS.goldSoft} strokeWidth="1.3" opacity="0.6" />
        <circle cx="46" cy="6" r="4" fill={COLORS.gold} />
      </svg>
    );
    return (
      <div
        onClick={() => setShowSplash(false)}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") setShowSplash(false);
        }}
        aria-label="Open సీయోను పాటలు"
        style={{
          position: "relative",
          minHeight: "100vh",
          width: "100%",
          background: COLORS.bg,
          color: COLORS.ink,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          cursor: "pointer",
          overflow: "hidden",
          ...teluguBody,
          transition: "background-color 0.2s ease, color 0.2s ease",
        }}
      >
        {cornerOrnament({ top: 18, left: 18 }, "none")}
        {cornerOrnament({ top: 18, right: 18 }, "scaleX(-1)")}
        {cornerOrnament({ bottom: 18, left: 18 }, "scaleY(-1)")}
        {cornerOrnament({ bottom: 18, right: 18 }, "scale(-1,-1)")}

        <h1
          style={{
            ...teluguDisplay,
            fontSize: 44,
            fontWeight: 700,
            color: COLORS.accent,
            margin: 0,
            textAlign: "center",
            padding: "0 24px",
          }}
        >
          సీయోను పాటలు
        </h1>

        <p
          style={{
            ...teluguBody,
            maxWidth: 360,
            margin: "22px auto 0 auto",
            padding: "0 30px",
            textAlign: "center",
            fontSize: 15,
            lineHeight: 1.7,
            color: COLORS.mutedText,
            fontStyle: "italic",
          }}
        >
          సీయోను నివాసులారా, నేను వచ్చి మీమధ్యను నివాసముచేతును; సంతోషముగానుండి పాటలు పాడుడి..
          <br />
          <span style={{ fontStyle: "normal", color: COLORS.gold, fontSize: 13 }}>జెకర్యా 2:10</span>
        </p>

        <div
          style={{
            position: "absolute",
            bottom: 26,
            left: 0,
            right: 0,
            textAlign: "center",
            fontSize: 12,
            letterSpacing: 1,
            color: COLORS.mutedText,
          }}
        >
          Created by Daniel Vijay G
        </div>
      </div>
    );
  }

  return (
    <div
      style={{
        minHeight: "100vh",
        background: COLORS.bg,
        color: COLORS.ink,
        ...teluguBody,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        padding: "0 0 48px 0",
        transition: "background-color 0.2s ease, color 0.2s ease",
      }}
    >
      <div style={{ width: "100%", maxWidth: 720, padding: "28px 20px 0 20px" }}>
        <div style={{ position: "relative", textAlign: "center", marginBottom: 18 }}>
          <button
            onClick={toggleDarkMode}
            aria-label={darkMode ? "Switch to light mode" : "Switch to dark mode"}
            title={darkMode ? "Switch to light mode" : "Switch to dark mode"}
            style={{
              position: "absolute",
              top: 0,
              right: 0,
              border: `1px solid ${COLORS.border}`,
              background: COLORS.cardBg,
              color: COLORS.accent,
              borderRadius: 8,
              width: 34,
              height: 34,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              cursor: "pointer",
            }}
          >
            {darkMode ? (
              <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="12" cy="12" r="5" />
                <path d="M12 1v2M12 21v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M1 12h2M21 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4" />
              </svg>
            ) : (
              <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
                <path d="M21 12.79A9 9 0 1111.21 3 7 7 0 0021 12.79z" />
              </svg>
            )}
          </button>
          <div style={{ fontSize: 13, letterSpacing: 3, color: COLORS.gold, marginBottom: 4 }}>
            ZION SONGS
          </div>
          <h1 style={{ ...teluguDisplay, fontSize: 34, fontWeight: 700, color: COLORS.accent, margin: 0 }}>
            సీయోను పాటలు
          </h1>
        </div>

        <div style={{ position: "sticky", top: 0, background: COLORS.bg, paddingBottom: 10, zIndex: 5 }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              background: COLORS.cardBg,
              border: `1.5px solid ${COLORS.borderStrong}`,
              borderRadius: 12,
              padding: "10px 14px",
              boxShadow: "0 1px 3px rgba(122,31,43,0.06)",
            }}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={COLORS.gold} strokeWidth="2" style={{ flexShrink: 0, marginRight: 10 }}>
              <circle cx="11" cy="11" r="7" />
              <line x1="21" y1="21" x2="16.65" y2="16.65" />
            </svg>
            <input
              ref={inputRef}
              value={query}
              onChange={(e) => {
                setQuery(e.target.value);
                setActiveNum(null);
                setActiveSection(null);
                setAlphaMode(false);
              }}
              placeholder="పాట సంఖ్య లేదా పేరు టైప్ చేయండి... (e.g. 4, అన్యజనులేల, or yehova)"
              style={{ border: "none", outline: "none", flex: 1, fontSize: 16, background: "transparent", color: COLORS.ink, ...teluguBody }}
            />
            {query && (
              <button
                onClick={() => {
                  setQuery("");
                  setActiveNum(null);
                  inputRef.current && inputRef.current.focus();
                }}
                style={{ border: "none", background: "transparent", cursor: "pointer", color: COLORS.gold, fontSize: 18, lineHeight: 1, padding: "2px 4px" }}
                aria-label="Clear search"
              >
                &times;
              </button>
            )}
          </div>

        </div>
      </div>

      <div style={{ width: "100%", maxWidth: 720, padding: "0 20px" }}>
        {activeSong ? (
          <SongPage
            song={activeSong}
            teluguDisplay={teluguDisplay}
            onBack={activeSection ? () => setActiveNum(null) : backToSearch}
            onPrev={goPrev}
            onNext={goNext}
            hasPrev={activeIndex > 0}
            hasNext={activeIndex >= 0 && activeIndex < navList.length - 1}
            position={`${activeIndex + 1} / ${navList.length}`}
            fontScale={fontScale}
            onFontScaleChange={changeFontScale}
            scriptMode={scriptMode}
            onToggleScriptMode={toggleScriptMode}
          />
        ) : activeSection ? (
          <SectionSongList section={activeSection} songs={sectionSongs} onOpen={openSong} onBack={backToContents} />
        ) : alphaMode ? (
          <AlphaList songs={alphaSorted} onOpen={openSong} onBack={() => setAlphaMode(false)} />
        ) : query.trim() ? (
          <ResultsList results={results} query={query.trim()} onOpen={openSong} />
        ) : (
          <>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", margin: "0 2px 10px 2px" }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: COLORS.accent, letterSpacing: 0.5 }}>CONTENTS</div>
              <button
                onClick={openAlphaList}
                style={{
                  border: `1px solid ${COLORS.border}`,
                  background: COLORS.cardBg,
                  color: COLORS.accent,
                  fontSize: 12.5,
                  fontWeight: 600,
                  cursor: "pointer",
                  borderRadius: 8,
                  padding: "6px 10px",
                }}
              >
                All Songs (A&ndash;Z)
              </button>
            </div>
            <ContentsView sections={SECTIONS} onSelect={openSection} />
          </>
        )}
      </div>
    </div>
  );
}

function highlightMatch(text, query) {
  if (!query) return text;
  const idx = normalize(text).indexOf(normalize(query));
  if (idx === -1) return text;
  return (
    <>
      {text.slice(0, idx)}
      <mark style={{ background: COLORS.markBg, color: COLORS.markText, borderRadius: 2 }}>{text.slice(idx, idx + query.length)}</mark>
      {text.slice(idx + query.length)}
    </>
  );
}

function ResultsList({ results, query, onOpen }) {
  if (results.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "48px 0", color: COLORS.mutedText }}>
        <div style={{ fontSize: 15 }}>ఫలితాలు కనబడలేదు (No matches found)</div>
        <div style={{ fontSize: 13, marginTop: 6 }}>Try a song number, or a Telugu word from the title.</div>
      </div>
    );
  }
  return (
    <div style={{ marginTop: 4 }}>
      <div style={{ fontSize: 12, color: COLORS.gold, margin: "10px 2px" }}>
        {results.length} result{results.length !== 1 ? "s" : ""}
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {results.map((s) => (
          <button
            key={s.num}
            onClick={() => onOpen(s.num)}
            style={{
              textAlign: "left",
              background: COLORS.cardBg,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 10,
              padding: "12px 14px",
              cursor: "pointer",
              display: "flex",
              gap: 12,
              alignItems: "flex-start",
              opacity: s.hasLyrics ? 1 : 0.7,
            }}
          >
            <span
              style={{
                flexShrink: 0,
                minWidth: 34,
                textAlign: "center",
                background: s.hasLyrics ? COLORS.chipBg : COLORS.pendingBg,
                color: s.hasLyrics ? COLORS.chipText : COLORS.pendingText,
                fontWeight: 700,
                fontSize: 13,
                borderRadius: 8,
                padding: "3px 6px",
              }}
            >
              {s.num}
            </span>
            <span style={{ flex: 1 }}>
              <span style={{ fontSize: 15, lineHeight: 1.4, color: COLORS.ink, display: "block" }}>
                {highlightMatch(s.title, /^\d+$/.test(query) ? "" : query)}
              </span>
              {!s.hasLyrics && (
                <span style={{ fontSize: 11.5, color: COLORS.pendingText }}>lyrics not added yet</span>
              )}
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

function ContentsView({ sections, onSelect }) {
  return (
    <div style={{ marginTop: 0 }}>
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {sections.map((sec, i) => (
          <button
            key={i}
            onClick={() => onSelect(sec)}
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              background: COLORS.cardBg,
              border: `1px solid ${COLORS.border}`,
              borderRadius: 10,
              padding: "10px 14px",
              cursor: "pointer",
              textAlign: "left",
              width: "100%",
            }}
          >
            <div style={{ display: "flex", alignItems: "baseline", gap: 10 }}>
              <span style={{ color: COLORS.gold, fontWeight: 700, fontSize: 13, minWidth: 18 }}>{i + 1}.</span>
              <div>
                <div style={{ fontSize: 15, color: COLORS.ink }}>{sec.name}</div>
                <div style={{ fontSize: 11.5, color: COLORS.mutedText }}>{sec.en}</div>
              </div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ fontSize: 12, color: COLORS.mutedText, whiteSpace: "nowrap" }}>p. {sec.pages}</div>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={COLORS.gold} strokeWidth="2">
                <path d="M9 18l6-6-6-6" />
              </svg>
            </div>
          </button>
        ))}
      </div>
    </div>
  );
}

function firstLetterOf(title) {
  const t = (title || "").trim();
  if (!t) return "#";
  // A Telugu akshara is a base consonant/vowel codepoint optionally followed
  // by combining vowel signs or virama -- the first codepoint is enough to
  // group by the base letter, which lines up with how the list is sorted.
  return Array.from(t)[0];
}

function AlphaList({ songs, onOpen, onBack }) {
  return (
    <div style={{ marginTop: 6 }}>
      <button
        onClick={onBack}
        style={{
          border: "none",
          background: "transparent",
          color: COLORS.gold,
          fontSize: 14,
          cursor: "pointer",
          padding: "4px 0",
          marginBottom: 10,
          display: "flex",
          alignItems: "center",
          gap: 4,
        }}
      >
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={COLORS.gold} strokeWidth="2">
          <path d="M15 18l-6-6 6-6" />
        </svg>
        Contents
      </button>

      <div style={{ marginBottom: 10 }}>
        <div style={{ fontSize: 17, color: COLORS.accent, fontWeight: 700 }}>All Songs (A&ndash;Z)</div>
        <div style={{ fontSize: 12.5, color: COLORS.mutedText }}>{songs.length} songs, sorted alphabetically by title</div>
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {songs.map((s, i) => {
          const letter = firstLetterOf(s.title);
          const prevLetter = i > 0 ? firstLetterOf(songs[i - 1].title) : null;
          const isNewGroup = letter !== prevLetter;
          return (
            <React.Fragment key={s.num}>
              {isNewGroup && (
                <div
                  style={{
                    position: "sticky",
                    top: 0,
                    zIndex: 1,
                    background: COLORS.gold,
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 14,
                    borderRadius: 8,
                    padding: "5px 12px",
                    marginTop: i === 0 ? 0 : 6,
                  }}
                >
                  {letter}
                </div>
              )}
              <button
                onClick={() => onOpen(s.num)}
                style={{
                  textAlign: "left",
                  background: COLORS.cardBg,
                  border: `1px solid ${COLORS.border}`,
                  borderRadius: 10,
                  padding: "12px 14px",
                  cursor: "pointer",
                  display: "flex",
                  gap: 12,
                  alignItems: "flex-start",
                  opacity: s.hasLyrics ? 1 : 0.7,
                }}
              >
                <span
                  style={{
                    flexShrink: 0,
                    minWidth: 22,
                    textAlign: "right",
                    color: COLORS.mutedText,
                    fontSize: 12.5,
                    paddingTop: 2,
                  }}
                >
                  {i + 1}.
                </span>
                <span style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ fontSize: 15, lineHeight: 1.4, color: COLORS.ink, display: "block" }}>{s.title}</span>
                  {!s.hasLyrics && <span style={{ fontSize: 11.5, color: COLORS.pendingText }}>lyrics not added yet</span>}
                </span>
                <span
                  style={{
                    flexShrink: 0,
                    minWidth: 34,
                    textAlign: "center",
                    background: s.hasLyrics ? COLORS.chipBg : COLORS.pendingBg,
                    color: s.hasLyrics ? COLORS.chipText : COLORS.pendingText,
                    fontWeight: 700,
                    fontSize: 13,
                    borderRadius: 8,
                    padding: "3px 6px",
                  }}
                >
                  {s.num}
                </span>
              </button>
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
}

function SectionSongList({ section, songs, onOpen, onBack }) {
  const addedCount = songs.filter((s) => s.hasLyrics).length;
  return (
    <div style={{ marginTop: 6 }}>
      <button
        onClick={onBack}
        style={{
          border: "none",
          background: "transparent",
          color: COLORS.gold,
          fontSize: 14,
          cursor: "pointer",
          padding: "4px 0",
          marginBottom: 10,
          display: "flex",
          alignItems: "center",
          gap: 4,
        }}
      >
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={COLORS.gold} strokeWidth="2">
          <path d="M15 18l-6-6 6-6" />
        </svg>
        Contents
      </button>

      <div style={{ marginBottom: 10 }}>
        <div style={{ fontSize: 17, color: COLORS.accent, fontWeight: 700 }}>{section.name}</div>
        <div style={{ fontSize: 12.5, color: COLORS.mutedText }}>
          {section.en} &middot; p. {section.pages} &middot; {addedCount} of {songs.length} added
        </div>
      </div>

      {songs.length === 0 ? (
        <div style={{ textAlign: "center", padding: "32px 0", color: COLORS.mutedText, fontSize: 14 }}>
          No songs found for this section's number range.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {songs.map((s) => (
            <button
              key={s.num}
              onClick={() => onOpen(s.num)}
              style={{
                textAlign: "left",
                background: COLORS.cardBg,
                border: `1px solid ${COLORS.border}`,
                borderRadius: 10,
                padding: "12px 14px",
                cursor: "pointer",
                display: "flex",
                gap: 12,
                alignItems: "flex-start",
                opacity: s.hasLyrics ? 1 : 0.7,
              }}
            >
              <span
                style={{
                  flexShrink: 0,
                  minWidth: 34,
                  textAlign: "center",
                  background: s.hasLyrics ? COLORS.chipBg : COLORS.pendingBg,
                  color: s.hasLyrics ? COLORS.chipText : COLORS.pendingText,
                  fontWeight: 700,
                  fontSize: 13,
                  borderRadius: 8,
                  padding: "3px 6px",
                }}
              >
                {s.num}
              </span>
              <span style={{ flex: 1 }}>
                <span style={{ fontSize: 15, lineHeight: 1.4, color: COLORS.ink, display: "block" }}>{s.title}</span>
                {!s.hasLyrics && <span style={{ fontSize: 11.5, color: COLORS.pendingText }}>lyrics not added yet</span>}
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function SongPage({ song, teluguDisplay, onBack, onPrev, onNext, hasPrev, hasNext, position, fontScale, onFontScaleChange, scriptMode, onToggleScriptMode }) {
  const scale = fontScale || 1;
  const lyricsFontSize = 16.5 * scale;
  const isEnglish = scriptMode === "en";
  const displaySong = useMemo(() => (isEnglish ? romanizeSong(song) : song), [song, isEnglish]);
  const englishStyle = { fontFamily: "system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif" };
  const displayStyle = isEnglish ? englishStyle : teluguDisplay;
  return (
    <div style={{ marginTop: 6, paddingBottom: 12 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10, gap: 8, flexWrap: "wrap" }}>
        <button
          onClick={onBack}
          style={{ border: "none", background: "transparent", color: COLORS.gold, fontSize: 14, cursor: "pointer", padding: "4px 0", display: "flex", alignItems: "center", gap: 4 }}
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={COLORS.gold} strokeWidth="2">
            <path d="M15 18l-6-6 6-6" />
          </svg>
          Back
        </button>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              border: `1px solid ${COLORS.border}`,
              borderRadius: 8,
              overflow: "hidden",
            }}
          >
            <button
              onClick={() => onFontScaleChange(-FONT_SCALE_STEP)}
              disabled={scale <= FONT_SCALE_MIN}
              aria-label="Decrease font size"
              title="Decrease font size"
              style={{
                border: "none",
                background: COLORS.cardBg,
                color: scale <= FONT_SCALE_MIN ? COLORS.disabled : COLORS.accent,
                fontSize: 13,
                fontWeight: 700,
                padding: "5px 10px",
                cursor: scale <= FONT_SCALE_MIN ? "default" : "pointer",
              }}
            >
              A&minus;
            </button>
            <div
              style={{
                fontSize: 11,
                color: COLORS.mutedText,
                padding: "0 8px",
                minWidth: 34,
                textAlign: "center",
                borderLeft: `1px solid ${COLORS.border}`,
                borderRight: `1px solid ${COLORS.border}`,
              }}
            >
              {Math.round(scale * 100)}%
            </div>
            <button
              onClick={() => onFontScaleChange(FONT_SCALE_STEP)}
              disabled={scale >= FONT_SCALE_MAX}
              aria-label="Increase font size"
              title="Increase font size"
              style={{
                border: "none",
                background: COLORS.cardBg,
                color: scale >= FONT_SCALE_MAX ? COLORS.disabled : COLORS.accent,
                fontSize: 14,
                fontWeight: 700,
                padding: "5px 10px",
                cursor: scale >= FONT_SCALE_MAX ? "default" : "pointer",
              }}
            >
              A+
            </button>
          </div>
          <button
            onClick={onToggleScriptMode}
            aria-label="Toggle English / Telugu lyrics script"
            title="Toggle English / Telugu lyrics script"
            style={{
              border: `1px solid ${COLORS.border}`,
              background: isEnglish ? COLORS.chipBg : COLORS.cardBg,
              color: isEnglish ? COLORS.chipText : COLORS.accent,
              borderRadius: 8,
              padding: "6px 10px",
              fontSize: 12.5,
              fontWeight: 700,
              cursor: "pointer",
            }}
          >
            {isEnglish ? "English" : "తెలుగు / English"}
          </button>
          <div style={{ fontSize: 12, color: COLORS.gold }}>{position}</div>
        </div>
      </div>

      <div
        style={{
          background: COLORS.cardBg,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 16,
          padding: "24px 22px",
          boxShadow: "0 2px 10px rgba(122,31,43,0.06)",
        }}
      >
        <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 4, flexWrap: "wrap" }}>
          <span style={{ ...displayStyle, fontSize: 26, fontWeight: 700, color: COLORS.accent }}>{displaySong.num}.</span>
          {displaySong.ref && <span style={{ ...displayStyle, fontSize: 13, color: COLORS.gold, fontStyle: "italic" }}>{displaySong.ref}</span>}
        </div>
        {displaySong.composer && (
          <div style={{ ...displayStyle, fontSize: 12.5, color: COLORS.mutedText, marginBottom: 4 }}>{displaySong.composer}</div>
        )}
        <div style={{ height: 1, background: COLORS.border, margin: "12px 0 16px 0" }} />

        {!displaySong.hasLyrics ? (
          <div style={{ textAlign: "center", padding: "28px 10px" }}>
            <div style={{ ...displayStyle, fontSize: 17, marginBottom: 8, color: COLORS.ink }}>{displaySong.title}</div>
            <div style={{ fontSize: 13, color: COLORS.pendingText, background: COLORS.pendingBg, display: "inline-block", padding: "6px 14px", borderRadius: 20 }}>
              lyrics not added yet
            </div>
          </div>
        ) : (
          <div style={{ ...displayStyle }}>
            {displaySong.refrain && (
              <div
                style={{
                  background: COLORS.refrainBg,
                  borderLeft: `3px solid ${COLORS.goldSoft}`,
                  borderRadius: 8,
                  padding: "12px 14px",
                  marginBottom: 16,
                  fontWeight: 600,
                  fontSize: lyricsFontSize,
                  lineHeight: 1.7,
                }}
              >
                {displaySong.refrain.label && (
                  <span style={{ color: COLORS.accent, marginRight: 6 }}>{displaySong.refrain.label}</span>
                )}
                {displaySong.refrain.lines.map((l, i) => (
                  <div key={i}>{l}</div>
                ))}
              </div>
            )}
            {displaySong.verses.map((v, i) => (
              <div key={i} style={{ marginBottom: 10, fontSize: lyricsFontSize, lineHeight: 1.7 }}>
                {v.num && <span style={{ fontWeight: 700, color: COLORS.accent, marginRight: 4 }}>{v.num}.</span>}
                {v.lines.map((l, j) => (
                  <div key={j} style={{ display: "inline" }}>
                    {l}
                    {j < v.lines.length - 1 ? <br /> : null}
                  </div>
                ))}
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", marginTop: 16 }}>
        <button
          onClick={onPrev}
          disabled={!hasPrev}
          style={{
            border: `1px solid ${COLORS.border}`,
            background: hasPrev ? COLORS.cardBg : COLORS.pendingBg,
            color: hasPrev ? COLORS.accent : COLORS.disabled,
            borderRadius: 10,
            padding: "10px 18px",
            fontSize: 14,
            fontWeight: 600,
            cursor: hasPrev ? "pointer" : "default",
          }}
        >
          &larr; Previous
        </button>
        <button
          onClick={onNext}
          disabled={!hasNext}
          style={{
            border: `1px solid ${COLORS.border}`,
            background: hasNext ? COLORS.cardBg : COLORS.pendingBg,
            color: hasNext ? COLORS.accent : COLORS.disabled,
            borderRadius: 10,
            padding: "10px 18px",
            fontSize: 14,
            fontWeight: 600,
            cursor: hasNext ? "pointer" : "default",
          }}
        >
          Next &rarr;
        </button>
      </div>
    </div>
  );
}
